// Repair the Claude Code Windows command generated by Secret Guard 0.2.2.
// Dry-run by default and preserve every non-xSOM hook.
import { spawnSync } from "node:child_process";
import {
  constants,
  copyFileSync,
  existsSync,
  readFileSync,
  writeFileSync,
} from "node:fs";
import {
  configureHost,
  defaultHostDefinitions,
  MANAGED_MARKER,
} from "../packages/vscode/src/host-config.ts";

if (process.platform !== "win32") throw new Error("Windows only");
if (process.argv.slice(2).some((arg) => arg !== "--apply")) {
  throw new Error(
    "Usage: node scripts/repair-claude-windows-hook.mjs [--apply]",
  );
}

const host = defaultHostDefinitions().find((entry) => entry.id === "claude");
if (host === undefined) throw new Error("Claude Code host definition missing");
const before = readFileSync(host.configPath, "utf8");
const root = JSON.parse(before);
const handlers = (root.hooks?.UserPromptSubmit ?? []).flatMap(
  (entry) => entry.hooks ?? [],
);
const owned = handlers.filter((entry) =>
  entry.command?.includes(MANAGED_MARKER),
);
if (owned.length !== 1) {
  throw new Error("Refusing to change an unrecognized Claude hook setup");
}

const previousCommand = owned[0].command;
const executable = /XSOM_SECRET_GUARD_EXECUTABLE='([^']+)'/u.exec(
  previousCommand,
)?.[1];
const hookPath = /XSOM_SECRET_GUARD_HOOK='([^']+)'/u.exec(previousCommand)?.[1];
if (
  executable === undefined ||
  hookPath === undefined ||
  !existsSync(executable) ||
  !existsSync(hookPath)
) {
  throw new Error("Managed Claude hook paths are missing or invalid");
}

const after = configureHost(before, host, executable, hookPath, "block");
const nextRoot = JSON.parse(after);
const nextHandlers = nextRoot.hooks.UserPromptSubmit.flatMap(
  (entry) => entry.hooks ?? [],
);
const nextOwned = nextHandlers.filter((entry) =>
  entry.command?.includes(MANAGED_MARKER),
);
if (nextOwned.length !== 1)
  throw new Error("Repaired Claude hook is ambiguous");

for (const [prompt, expected] of [
  ["Bonjour", 0],
  [
    "Analyse cette configuration : PASSWORD=definitely-not-a-real-secret-123",
    2,
  ],
]) {
  const result = spawnSync(
    "powershell.exe",
    ["-NoProfile", "-NonInteractive", "-Command", nextOwned[0].command],
    {
      input: JSON.stringify({ hook_event_name: "UserPromptSubmit", prompt }),
      encoding: "utf8",
      timeout: 10_000,
      windowsHide: true,
    },
  );
  let cleanAllowed = false;
  const stdout = result.stdout ?? "";
  const stderr = result.stderr ?? "";
  if (expected === 0) {
    try {
      cleanAllowed = JSON.parse(stdout).continue === true;
    } catch {
      cleanAllowed = false;
    }
  }
  const detectionReported = stderr.includes("Secret Guard detected password");
  const syntheticValueLeaked = stderr.includes(
    "definitely-not-a-real-secret-123",
  );
  if (
    result.error ||
    result.status !== expected ||
    (expected === 0 && !cleanAllowed) ||
    (expected === 2 && (!detectionReported || syntheticValueLeaked))
  ) {
    throw new Error(
      `Claude hook verification failed (expected=${expected}, actual=${String(result.status)}, spawn=${result.error ? "failed" : "ok"}, cleanAllowed=${String(cleanAllowed)}, detectionReported=${String(detectionReported)}, syntheticValueLeaked=${String(syntheticValueLeaked)}); configuration unchanged`,
    );
  }
}

console.log("Claude command verified: clean exit 0; fake password exit 2.");
if (after === before) {
  console.log("Configuration already repaired.");
} else if (!process.argv.includes("--apply")) {
  console.log(
    `Ready to repair only the Secret Guard entry in ${host.configPath}`,
  );
} else {
  if (readFileSync(host.configPath, "utf8") !== before) {
    throw new Error("Configuration changed during verification");
  }
  const backup = `${host.configPath}.backup-before-claude-repair-${Date.now()}`;
  copyFileSync(host.configPath, backup, constants.COPYFILE_EXCL);
  writeFileSync(host.configPath, after, "utf8");
  console.log(`Repaired. Backup: ${backup}`);
  console.log(
    "Claude Code watches settings.json and reloads hooks automatically.",
  );
}
